import java.util.*;

class Solution {
  public String getPermutation(int n, int k) {
    List<Integer> digits = new ArrayList<>();
    int[] fact = new int[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
      digits.add(i);
      fact[i] = fact[i - 1] * i;
    }
    StringBuilder sb = new StringBuilder();
    k--;
    for (int i = n; i >= 1; i--) {
      int idx = k / fact[i - 1];
      sb.append(digits.remove(idx));
      k %= fact[i - 1];
    }
    return sb.toString();
  }
}
